public class BadHostnameVerifierDetector extends Detector implements SourceCodeScanner {

    private static final Implementation IMPLEMENTATION = new Implementation(
            BadHostnameVerifierDetector.class,
            Scope.JAVA_FILE_SCOPE
    );

    public static final Issue ISSUE = Issue.create(
            "BadHostnameVerifier",
            "Insecure HostnameVerifier",
            "This `HostnameVerifier` implementation always returns `true`, which will trust " +
            "any hostname presented by the peer. This can lead to man-in-the-middle attacks " +
            "because TLS certificate hostnames are not verified.",
            Category.SECURITY,
            6,
            Severity.WARNING,
            IMPLEMENTATION
    );

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (!implementsHostnameVerifier(node)) return;
                for (UMethod method : node.getMethods()) {
                    if (isVerifyMethod(method)) {
                        if (alwaysReturnsTrue(method, context)) {
                            Location location = context.getNameLocation(method);
                            context.report(ISSUE, location, "Insecure `HostnameVerifier`: `verify` always returns `true`");
                        }
                    }
                }
            }
        };
    }

    private static boolean implementsHostnameVerifier(UClass node) {
        PsiClass psi = node.getJavaPsi();
        if (psi == null) return false;
        PsiClass[] interfaces = psi.getInterfaces();
        for (PsiClass iface : interfaces) {
            if ("javax.net.ssl.HostnameVerifier".equals(iface.getQualifiedName())) {
                return true;
            }
        }
        return false;
    }

    private static boolean isVerifyMethod(UMethod method) {
        if (!"verify".equals(method.getName())) return false;
        PsiMethod psi = method.getJavaPsi();
        if (psi == null) return false;
        PsiClass[] paramTypes = psi.getParameterList().getParametersTypes(); no.
        // Simpler via method.getParameterList().getParametersCount() and types
        if (method.getUastParameters().size() != 2) return false;
        // check param types String and javax.net.ssl.SSLSession
        // Use psi parameters
        com.intellij.psi.PsiParameter[] params = psi.getParameterList().getParameters();
        return params.length == 2
                && "java.lang.String".equals(params[0].getType().getCanonicalText())
                && "javax.net.ssl.SSLSession".equals(params[1].getType().getCanonicalText());
    }

    private static boolean alwaysReturnsTrue(UMethod method, JavaContext context) {
        UExpression body = method.getUastBody();
        if (body == null) return false;
        if (body instanceof UBlockExpression block) {
            List<UExpression> expressions = block.getExpressions();
            if (expressions.size() == 1 && expressions.get(0) instanceof UReturnExpression ret) {
                return evaluatesToTrue(ret.getReturnExpression(), context);
            }
            // Check all return statements
            boolean[] foundReturn = new boolean[1];
            boolean[] allTrue = new boolean[]{true};
            body.accept(new AbstractUastVisitor() {
                @Override
                public boolean visitReturnExpression(@NotNull UReturnExpression node) {
                    foundReturn[0] = true;
                    if (!evaluatesToTrue(node.getReturnExpression(), context)) {
                        allTrue[0] = false;
                    }
                    return super.visitReturnExpression(node);
                }
            });
            return foundReturn[0] && allTrue[0];
        } else if (body instanceof UReturnExpression ret) {
            return evaluatesToTrue(ret.getReturnExpression(), context);
        }
        return false;
    }

    private static boolean evaluatesToTrue(@Nullable UExpression expr, JavaContext context) {
        if (expr == null) return false;
        Object value = ConstantEvaluator.evaluate(context, expr);
        return Boolean.TRUE.equals(value);
    }
}

