private static boolean implementsHostnameVerifier(@NotNull UClass node) {
    PsiClass psi = node.getJavaPsi();
    if (psi == null) {
        return false;
    }
    for (PsiClass iface : psi.getInterfaces()) {
        if ("javax.net.ssl.HostnameVerifier".equals(iface.getQualifiedName())) {
            return true;
        }
    }
    PsiClass superClass = psi.getSuperClass();
    if (superClass != null && "javax.net.ssl.HostnameVerifier".equals(superClass.getQualifiedName())) {
        return true;
    }
    // recursively check super classes
    while (superClass != null) {
        for (PsiClass iface : superClass.getInterfaces()) {
            if ("javax.net.ssl.HostnameVerifier".equals(iface.getQualifiedName())) {
                return true;
            }
        }
        superClass = superClass.getSuperClass();
    }
    return false;
